function start(name){state.started=true;state.name='ASH';state.party=[makeMon(name,5)];state.seen=[name];state.log=[];save();closeOverlay();addLog(`Professor Oak gave you ${name}. A perfect partner for the road ahead!`);addLog('A friendly breeze drifts through Pallet Town. Your adventure begins.');render()}
function explore(){if(state.route===0){state.route=1;state.day++;addLog('You wave goodbye to Professor Oak and follow the path north. Viridian Forest awaits!');render();return}if(state.wins>=3&&state.route<3){state.route++;state.wins=0;state.day++;addLog(`With your confidence growing, you travel onward to ${routes[state.route-1][0]}.`);render();return}if(state.party.every(m=>m.hp<=0)){addLog('Your team needs a rest before another encounter. Visit the Pokémon Center.');return}if(Math.random()<.12){state.day++;if(state.potions<5){state.potions++;addLog('You found a Potion tucked beside the path!')}else{state.balls++;addLog('A kind hiker left a Poké Ball on a trail marker!')}render();return}const route=routes[Math.min(state.route-1,routes.length-1)],name=route[2+Math.floor(Math.random()*(route.length-2))],level=3+Math.min(state.route,3)+Math.floor(Math.random()*3),mon=makeMon(name,level);state.seen=[...new Set([...state.seen,name])];battle={foe:mon,guard:0};addLog(`The tall grass stirs... a wild ${name} appeared!`);render();battleModal()}
function battleModal(message=''){if(!battle)return;const m=state.party.find(x=>x.hp>0),foe=battle.foe;if(!m){closeOverlay();battle=null;addLog('Your Pokémon are all worn out. The Center will get them back on their feet.');render();return}let hpPct=Math.max(0,foe.hp/foe.maxHp*100);overlay(`<div class="modal"><div class="modal-kicker">WILD ENCOUNTER · ROUTE ${String(state.route).padStart(2,'0')}</div><h1>A wild ${esc(foe.name)}!</h1><p>${message||'What will you do, Trainer?'}</p><div class="battle-card"><div class="battle-mon"><span class="battle-emoji">${species[m.name].emoji}</span><div class="battle-mon-label">YOUR PARTNER</div><div class="battle-mon-name">${esc(m.name)} · LV ${m.level}</div><div class="hp-track"><div class="hp-fill ${m.hp/m.maxHp<.25?'low':''}" style="width:${m.hp/m.maxHp*100}%"></div></div><div class="battle-hp">HP ${m.hp} / ${m.maxHp}</div></div><div class="battle-mon foe"><span class="battle-emoji">${species[foe.name].emoji}</span><div class="battle-mon-label">WILD POKÉMON</div><div class="battle-mon-name">${esc(foe.name)} · LV ${foe.level}</div><div class="hp-track"><div class="hp-fill ${hpPct<25?'low':''}" style="width:${hpPct}%"></div></div><div class="battle-hp">HP ${foe.hp} / ${foe.maxHp}</div></div></div><div class="battle-actions"><button class="action primary" id="fightBtn">⚔ &nbsp; FIGHT</button><button class="action" id="throwBtn" ${state.balls<=0?'disabled':''}>◉ &nbsp; POKÉ BALL (${state.balls})</button><button class="action" id="potionBtn" ${state.potions<=0?'disabled':''}>✚ &nbsp; USE POTION (${state.potions})</button><button class="action" id="runBtn">↗ &nbsp; RUN</button></div><div class="notice">Your first Pokémon leads the party. Damage depends on level and type.</div></div>`);$('fightBtn').onclick=fight;$('throwBtn').onclick=throwBall;$('potionBtn').onclick=usePotion;$('runBtn').onclick=run}
function fight(){if(!battle)return;let m=state.party.find(x=>x.hp>0);if(!m){battleModal();return}const d=species[m.name],f=species[battle.foe.name];let bonus=d.type===f.type?1.12:1,damage=Math.max(3,Math.floor((d.attack+m.level+Math.random()*5)*bonus/2));battle.foe.hp=Math.max(0,battle.foe.hp-damage);if(battle.foe.hp<=0){const defeated=battle.foe.name;state.wins++;const xp=8+battle.foe.level*2;m.xp+=xp;let msg=`${m.name} used ${d.move}! The wild ${defeated} fainted. ${m.name} gained ${xp} XP.`;if(m.xp>=m.level*12){m.xp-=m.level*12;m.level++;let increase=Math.ceil(species[m.name].hp/5);m.maxHp+=increase;m.hp=Math.min(m.maxHp,m.hp+increase);msg+=` ${m.name} grew to level ${m.level}!`}if(state.wins>=3&&state.route<=3){state.badges=Math.max(state.badges,state.route);msg+=' You earned a trail badge!'}battle=null;closeOverlay();addLog(msg);save();render();return}let enemyDamage=Math.max(2,Math.floor((f.attack+battle.foe.level+Math.random()*3)/3));if(battle.guard){enemyDamage=Math.ceil(enemyDamage/2);battle.guard=0}m.hp=Math.max(0,m.hp-enemyDamage);battleModal(`${m.name} used ${d.move} for ${damage} damage! Wild ${battle.foe.name} hit back for ${enemyDamage}.`)}
function throwBall(){if(!battle||state.balls<=0)return;state.balls--;let foe=battle.foe;let chance=.28+(1-foe.hp/foe.maxHp)*.62;if(Math.random()<chance){if(state.party.length<6){state.party.push({...foe,hp:Math.max(1,foe.hp)});state.caught++;addLog(`Click! You caught ${foe.name}! It joined your party.`)}else{state.caught++;addLog(`Click! You caught ${foe.name}! Your party is full, so it went to the PC.`)}battle=null;closeOverlay();save();render()}else{let m=state.party.find(x=>x.hp>0);let damage=Math.max(2,Math.floor((species[foe.name].attack+foe.level)/3));m.hp=Math.max(0,m.hp-damage);battleModal(`The Poké Ball shook... and ${foe.name} broke free! ${m.name} took ${damage} damage.`)}}
function usePotion(){if(!battle||state.potions<=0)return;let m=state.party.find(x=>x.hp>0);if(m.hp===m.maxHp){battleModal(`${m.name} is already at full health.`);return}state.potions--;const healed=Math.min(20,m.maxHp-m.hp);m.hp+=healed;const damage=Math.max(2,Math.floor((species[battle.foe.name].attack+battle.foe.level)/3));m.hp=Math.max(0,m.hp-damage);battleModal(`You restored ${healed} HP to ${m.name}. The wild Pokémon countered for ${damage} damage.`);save()}
function run(){if(!battle)return;let foe=battle.foe.name;battle=null;closeOverlay();addLog(`You slipped away from the wild ${foe}. Better to be prepared!`);render()}
function heal(){let total=0;state.party.forEach(m=>{total+=m.maxHp-m.hp;m.hp=m.maxHp});state.potions=Math.min(5,state.potions+1);state.day++;addLog(`Nurse Joy restored your Pokémon to full health${total?' — they feel ready to go!':' and gave you a Potion for the road.'}`);render()}
function openBag(){overlay(`<div class="modal"><div class="modal-kicker">TRAINER'S BAG</div><h1>Pack for the road.</h1><p>A few useful things for your travels through Kanto.</p><div class="bag-line"><span>POKÉ BALLS</span><strong>${state.balls}</strong></div><div class="bag-line"><span>POTIONS</span><strong>${state.potions}</strong></div><div class="bag-line"><span>POKÉDOLLARS</span><strong>₽ ${state.money}</strong></div><div class="notice">Visit the Pokémon Center to rest and receive a complimentary Potion.</div><button class="modal-close" id="modalClose">CLOSE</button></div>`);$('modalClose').onclick=closeOverlay}
function openDex(){let rows=state.seen.map(n=>`<div class="bag-line"><span>${species[n].emoji} &nbsp; ${esc(n)}</span><strong>${species[n].type}</strong></div>`).join('');overlay(`<div class="modal"><div class="modal-kicker">PROFESSOR OAK'S RESEARCH</div><h1>Pokédex</h1><p>Pokémon you've encountered on your journey: <strong>${state.seen.length}</strong></p>${rows||'<div class="empty-party">No entries yet. Explore to discover Pokémon.</div>'}<button class="modal-close" id="modalClose">CLOSE</button></div>`);$('modalClose').onclick=closeOverlay}
function toggleSound(){sound=!sound;$('soundBtn').textContent=sound?'♫ SOUND ON':'♪ SOUND OFF';if(sound){try{let ctx=new(window.AudioContext||window.webkitAudioContext)(),o=ctx.createOscillator(),g=ctx.createGain();o.connect(g);g.connect(ctx.destination);o.frequency.value=523;g.gain.value=.025;o.start();o.stop(ctx.currentTime+.12)}catch{}}}
$('exploreBtn').onclick=explore;$('healBtn').onclick=heal;$('bagBtn').onclick=openBag;$('dexBtn').onclick=openDex;$('soundBtn').onclick=toggleSound;$('resetBtn').onclick=()=>{overlay(`<div class="modal"><div class="modal-kicker">START OVER</div><h1>A fresh adventure?</h1><p>This will erase your saved journey and let you choose a new partner.</p><div class="battle-actions"><button class="action" id="cancelReset">KEEP PLAYING</button><button class="action primary" id="confirmReset">NEW GAME</button></div></div>`);$('cancelReset').onclick=closeOverlay;$('confirmReset').onclick=()=>{localStorage.removeItem('quiet-route');state=fresh();battle=null;starterModal();render()}};
$('modalRoot').addEventListener('click',e=>{if(e.target===$('modalRoot')&&state.started&&!battle)closeOverlay()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&inModal&&state.started&&!battle)closeOverlay()});render();
})();
</script>
</body>
</html>

